        }
      ],
      "key":"glossary_graph_native_odd_index",
      "label":"Glossary graph-native ODD index"
    },
    {
      "conditions": [],
      "definition": "Index in urn:stdo:bounded-context:traversal-occurrence-profile, declared by TRAVERSAL_OCCURRENCE Position. Traversal Occurrence Profile/Sigma_occurrence is owned at position with imported-calculus-boundary as its relation clause. Occurrence, Framework Event, Typed Lineage, Mutable Subject, Event Frontier and Traversal Occurrence Profile Basis route respectively to occurrence-identity, candidate-judgment-event-and-relation-separation, causality-and-typed-lineage, mutable-subject-effect-relation, event-frontier-and-projection and exact-profile-identity, with no relation clause specified. Cause-separated stop/decision values are refusal(constraint), refusal(basis), refused(constraint), refused(basis), partial_effect(not_attained), partial_effect(undecided), partial(not_attained), partial(undecided); their owner is closed-constraint-judgment-residual-and-stop-kinds, with AC-007 and FOUNDATIONS Results as relation clauses.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":329,
          "quote":"| stop and decision values split by cause: `refusal(constraint)`; `refusal(basis)`; `refused(constraint)`; `refused(basis)`; `partial_effect(not_attained)`; `partial_effect(undecided)`; `partial(not_attained)`; `partial(undecided)` | `urn:stdo:bounded-context:traversal-occurrence-profile` | [`TRAVERSAL_OCCURRENCE.md#closed-constraint-judgment-residual-and-stop-kinds`](TRAVERSAL_OCCURRENCE.md#closed-constraint-judgment-residual-and-stop-kinds) | [`AXIOMATIC_CALCULUS.md#ac-007-constraint-and-refusal`](AXIOMATIC_CALCULUS.md#ac-007-constraint-and-refusal); [`FOUNDATIONS.md#results`](FOUNDATIONS.md#results) |",
          "section_id":"repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/GLOSSARY.md#GLOSSARY%2F15.%20Traversal%20occurrence",
